import numpy as np
from scipy.ndimage import label
from scipy.optimize import least_squares
f=np.load('source_pixels.npz')['rgb']; yy,xx=np.indices(f.shape[1:3]); bg=np.median(f[1:13],axis=0)
# top sphere silhouette chromatic large difference. fit gray bg exclusion, outer r>bg +30 g>bg+15, constrained region
tr=np.load('.tmp/tracks.npz')['big']
for t in [0,1,3,5,8,10,12,15,20,25,30,40]:
 a=f[t].astype(float);r,g,b=a.transpose(2,0,1);cx=tr[t,0];cy=tr[t,1]
 m=(r>65)&(r-g>16)&(g-b>16)&(yy<cy+3)&(yy>cy-12)&(abs(xx-cx)<12)
 pts=[]
 for y in range(int(cy)-10,int(cy)+3):
